def with_setup(setup=None, teardown=None):
    def decorate(func):
        def wrapped():
            if setup:
                setup()
            try:
                func()
            finally:
                if teardown:
                    teardown()
        wrapped.__name__ = func.__name__
        return wrapped
    return decorate

import contextlib


@contextlib.contextmanager
def assert_raises(exc_class):
    try:
        yield
    except exc_class:
        return
    raise AssertionError("%s not raised" % exc_class)
